    if (gran === "week") return fmtMD(b) + "~";
    return Number(b.slice(5, 7)) === 1 || isFirst ? b.slice(2, 4) + "." + Number(b.slice(5, 7)) + "월" : Number(b.slice(5, 7)) + "월";
