    renderHBars("payChart", "pay", "pays", "payTitle", "결제수단별 " + compLabel());
    if (WHOS.length > 1) renderHBars("whoChart", "who", "whos", "whoTitle", "구성원별 " + compLabel());
    else $("whoCard").hidden = true;
