  $("csvBtn").addEventListener("click", downloadCsv);
  window.addEventListener("resize", debounce(function () { if (renderUnreceivedRange()) return; renderTrend(); renderWeek(); renderBudget(); }, 180));

  // ---------- 초기 진입
