async function handleMyCategoryKeywordsBulkSave(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const householdId = String(form.get("household_id") || "").trim();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const returnTo = String(form.get("return_to") || "");
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected) return redirectResponse("/my?err=no_household");
  if (!canManageMyHousehold(selected.role)) return redirectResponse(keywordEditorLocation(returnTo, month, selected.id, { err: "keyword_manage_only" }));
  const names = form.getAll("kw_name").map((v) => String(v || "").trim().slice(0, 80));
  const keywords = form.getAll("kw_keywords").map((v) => String(v || ""));
  // V22.9.34 감사 S4: 카드마다 그릴 때의 키워드(kw_orig)를 함께 받아, 사용자가 바꾼 카드만 저장한다.
  // 예전에는 모든 카드를 그대로 다시 저장해, 읽기 실패로 예시가 그려진 화면이나 오래 열어 둔 화면에서
  // 저장하면 다른 분류의 키워드까지 예시·옛 값으로 바뀌었다. kw_orig 가 없는 폼은 배포 전 화면이다.
  const origs = form.getAll("kw_orig").map((v) => String(v ?? ""));
  if (names.length && origs.length !== names.length) return redirectResponse(keywordEditorLocation(returnTo, month, selected.id, { err: "keyword_form_stale" }));
  try {
    const outcome = await withHouseholdSettingsRmw(env, selected.id, async ({ assertFresh }) => {
      // V22.9.26: strict 읽기 — 읽기 실패를 빈 값으로 보면 기존 키워드가 모두 사라진다.
      const map = await fetchCategoryKeywordMap(env, selected.id, { strict: true });
      let changed = 0;
      let conflicts = 0;
      for (let i = 0; i < names.length; i++) {
        const name = names[i];
        if (!name) continue;
        const next = normalizeCategoryKeywords(keywords[i] || "");
        const orig = normalizeCategoryKeywords(origs[i] || "");
        if (sameKeywordList(next, orig)) continue;
        const current = keywordEditorCardKeywords(name, map);
        // 화면을 연 뒤 다른 곳에서 이 분류를 바꿨다면 덮어쓰지 않는다.
        if (!sameKeywordList(current.keywords, orig)) { conflicts += 1; continue; }
        map[current.key] = next;
        changed += 1;
      }
      if (changed) {
        assertFresh();
        await saveCategoryKeywordMap(env, selected.id, map);
      }
      return { changed, conflicts };
    });
    if (outcome.conflicts) return redirectResponse(keywordEditorLocation(returnTo, month, selected.id, { err: outcome.changed ? "category_keywords_partly_conflict" : "category_keywords_conflict" }));
    return redirectResponse(keywordEditorLocation(returnTo, month, selected.id, { msg: outcome.changed ? "category_keywords_saved" : "category_keywords_unchanged" }));
  } catch (err) {
    rememberOpsEvent({ kind: "my_category_keywords_bulk_failed", severity: "warn", path: "/my/category-keywords/bulk-save", method: "POST", detail: safeError(err) });
    return redirectResponse(keywordEditorLocation(returnTo, month, selected.id, { err: "category_keywords_save_failed" }));
  }
}

async function handleMyRecurringSave(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const householdId = String(form.get("household_id") || "").trim();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected) return redirectResponse("/my?err=no_household");
  if (!canManageMyHousehold(selected.role)) return redirectResponse(mySettingsLocation(month, selected.id, { err: "write_not_allowed" }));
  const formProblem = recurringFormProblem(form);
  if (formProblem) return redirectResponse(mySettingsLocation(month, selected.id, { err: formProblem }));
  const memo = String(form.get("memo") || "").trim().slice(0, 120);
  const amount = Math.max(0, Math.round(parseAmountValue(form.get("amount") || "0")));
  if (!memo || !amount || amount > MAX_TRANSACTION_AMOUNT) return redirectResponse(mySettingsLocation(month, selected.id, { err: "recurring_missing" }));
  const ruleId = String(form.get("id") || "").trim();
  const type = normalizeTransactionType(String(form.get("type") || "expense"));
  const row = {
    household_id: selected.id,
    type,
    amount,
    // V22.9.76: 분류를 비우면 구분에 맞는 기본값을 쓴다. 예전에는 폼이 "정기지출"을 미리 채우고 서버도 같은 값을 넣어,
    // 구분만 수입으로 바꾼 정기 수입(예: 수당)이 매달 분류 "정기지출"인 수입 거래로 기록됐다.
    category: String(form.get("category") || "").trim().slice(0, 80) || defaultRecurringCategory(type),
    memo,
    payment_method: String(form.get("payment_method") || "").trim().slice(0, 80),
    day_of_month: normalizeRecurringDay(form.get("day_of_month")),
    is_active: true,
  };
  try {
    // V22.9.37 감사 T8: 새 규칙의 지출자는 만든 사람이다. 수정은 지출자를 보내지 않으면 기존 지출자를 그대로 두고(예전에는
    // 고친 사람으로 바뀌었다), 보냈으면 자동 반영과 같은 자격(소유자·관리자·구성원)일 때만 받는다.
    const requestedSpender = String(form.get("user_id") || "").trim();
    if (!ruleId) row.user_id = userId;
    else if (requestedSpender) {
      if (!recurringSpenderEligible(await fetchRawHouseholdMembers(env, selected.id), requestedSpender)) return redirectResponse(mySettingsLocation(month, selected.id, { err: "recurring_spender_ineligible" }));
      row.user_id = requestedSpender;
    }
    if (!ruleId) await markRecurringAppliedIfRecordedThisMonth(env, selected.id, row);
    await withHouseholdDatabaseLease(env, selected.id, async ({ assertFresh }) => {
      const existing = ruleId ? await fetchRecurringRuleByIdStrict(env, ruleId) : null;
      if (ruleId && (!existing || String(existing.household_id) !== String(selected.id))) throw new Error("recurring_scope_invalid");
      assertFresh();
      // V22.9.76 감사 D-10: 놓친 지난달 몫은 고치기 전 값으로 먼저 넣고, 고친 값은 다음 반영부터 쓴다.
      if (existing) { await settleRecurringBeforeEdit(env, selected.id, existing, row); assertFresh(); }
      if (!ruleId && await findRecentDuplicateRecurringRule(env, selected.id, row)) return;
      await supabase(env, ruleId ? `/rest/v1/accountbook_recurring?id=eq.${encodeURIComponent(ruleId)}&household_id=eq.${encodeURIComponent(selected.id)}` : "/rest/v1/accountbook_recurring", {
        method: ruleId ? "PATCH" : "POST",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify(row),
      });
    });
    return redirectResponse(mySettingsLocation(month, selected.id, { msg: "recurring_saved" }));
  } catch (err) {
    // V22.9.76 감사 D-25: 두 번 누른 저장의 두 번째 요청은 첫 요청이 쓰는 동안 잠금을 못 얻는다. 저장 공간 장애로 안내하지 않는다.
    return redirectResponse(mySettingsLocation(month, selected.id, { err: isUncertainStorageWrite(err) ? "db_write_unknown" : /settings_rmw_busy/.test(safeError(err)) ? "recurring_busy" : "recurring_table_required" }));
  }
}

async function handleMyRecurringDelete(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const householdId = String(form.get("household_id") || "").trim();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const id = String(form.get("id") || "").trim();
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected) return redirectResponse("/my?err=no_household");
  if (!canManageMyHousehold(selected.role)) return redirectResponse(mySettingsLocation(month, selected.id, { err: "write_not_allowed" }));
  try {
    await withHouseholdDatabaseLease(env, selected.id, async ({ assertFresh }) => {
      assertFresh();
      // V22.9.63 감사(웹 1): 지운 행이 없으면(다른 가계부 항목이거나 이미 지워짐) 성공이라고 하지 않는다. 관리자 경로와 같다.
      const deleted = await supabase(env, `/rest/v1/accountbook_recurring?id=eq.${encodeURIComponent(id)}&household_id=eq.${encodeURIComponent(selected.id)}`, { method: "DELETE", headers: { Prefer: "return=representation" } });
      if (!Array.isArray(deleted) || !deleted.length) throw new Error("recurring_not_found");
    });
    return redirectResponse(mySettingsLocation(month, selected.id, { msg: "recurring_deleted" }));
  } catch (err) {
    rememberOpsEvent({ kind: "my_recurring_delete_failed", severity: "warn", path: "/my/recurring/delete", method: "POST", detail: safeError(err) });
    const notFound = String(err?.message || "") === "recurring_not_found";
    return redirectResponse(mySettingsLocation(month, selected.id, { err: notFound ? "recurring_not_found" : isUncertainStorageWrite(err) ? "db_write_unknown" : "recurring_delete_failed" }));
  }
}

// V22.9.34 감사 T3: 새 정기 규칙을 만들 때 이번 달에 같은 지출(같은 금액·내용)을 이미 기록했으면
// last_applied_month 를 이번 달로 채운다. 그러지 않으면 자동·수동 반영이 이번 달에 한 번 더 넣었다.
async function markRecurringAppliedIfRecordedThisMonth(env, householdId, row, rowsHint = null) {
  const thisMonth = currentMonthKst();
  const memoKey = normalizeText(row.memo || "");
  if (!memoKey || !(Number(row.amount) > 0)) return false;
  // V22.9.37: 부르는 쪽이 이번 달 같은 종류의 기록을 이미 읽어 두었으면(rowsHint) 다시 읽지 않는다.
  const rows = Array.isArray(rowsHint) ? rowsHint : await fetchAdminRows(env, { month: thisMonth, householdId, type: row.type === "income" ? "income" : "expense" });
  const recorded = safeArray(rows).some((item) => Number(item.amount) === Number(row.amount)
    && (normalizeText(item.memo || "") === memoKey || normalizeText(item.raw_text || "").includes(memoKey)));
  if (recorded) row.last_applied_month = thisMonth;
  return recorded;
}

// V22.9.76 감사 D-26: 정기 항목 입력값을 바꿔 넣고 성공이라 답하지 않는다. 지정일은 1~31(그 달에 없는 날은 말일에 기록),
// 금액은 음수를 받지 않는다(예전에는 0·32·빈칸이 1·31로, "-5000"이 5,000원으로 저장됐다). 문제가 없으면 빈 문자열.
function recurringFormProblem(form) {
  const day = String(form.get("day_of_month") ?? "").trim();
  const digits = day.length >= 1 && day.length <= 2 && [...day].every((ch) => ch >= "0" && ch <= "9");
  if (!digits || Number(day) < 1 || Number(day) > 31) return "recurring_day_invalid";
  if (/-/.test(String(form.get("amount") ?? ""))) return "recurring_amount_invalid";
  return "";
}

// V22.9.76 감사 D-25: 같은 정기 항목을 두 번 보내면(두 번 누름·다시 보내기) 규칙이 둘 생겨 다달이 두 번 기록됐다.
// 가계부 쓰기 잠금 안에서 부른다. 같은 구분·금액·지정일·메모·분류·지출자의 켜진 규칙이 10분 안에 만들어졌으면(만든 시각을
// 모르면 있는 것만으로) 같은 요청으로 보고 새로 만들지 않는다.
const RECURRING_DUPLICATE_WINDOW_MS = 10 * 60 * 1000;
async function findRecentDuplicateRecurringRule(env, householdId, row = {}) {
  const same = (a, b) => normalizeText(String(a ?? "")) === normalizeText(String(b ?? ""));
  return safeArray(await fetchRecurringStrict(env, householdId)).find((rule) => rule.is_active !== false
    && (rule.type === "income" ? "income" : "expense") === (row.type === "income" ? "income" : "expense")
    && Number(rule.amount) === Number(row.amount) && Number(rule.day_of_month) === Number(row.day_of_month)
    && same(rule.memo, row.memo) && same(rule.category, row.category) && String(rule.user_id || "") === String(row.user_id || "")
    && (!Number.isFinite(Date.parse(String(rule.created_at || ""))) || Date.now() - Date.parse(String(rule.created_at)) < RECURRING_DUPLICATE_WINDOW_MS)) || null;
}

async function handleRecurringCandidateConfirm(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const householdId = String(form.get("household_id") || "").trim();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const returnTo = `/smart-tools?month=${encodeURIComponent(month)}&household_id=${encodeURIComponent(householdId)}`;
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected || String(selected.id) !== householdId) return redirectResponse("/my?err=no_household");
  if (!canManageMyHousehold(selected.role)) return redirectResponse(`${returnTo}&err=manage_required`);
  if (String(form.get("confirmed") || "") !== "yes") return redirectResponse(`${returnTo}&err=confirmation_required`);
  const memo = String(form.get("memo") || "").trim().slice(0, 120);
  const amount = Math.max(0, Math.min(2_000_000_000, Math.round(parseAmountValue(form.get("amount") || "0"))));
  if (!memo || !amount) return redirectResponse(`${returnTo}&err=recurring_missing`);
  const row = {
    household_id: selected.id,
    type: "expense",
    amount,
    category: String(form.get("category") || "정기지출").trim().slice(0, 80) || "정기지출",
    memo,
    payment_method: String(form.get("payment_method") || "").trim().slice(0, 80),
    day_of_month: normalizeRecurringDay(form.get("day_of_month")),
    user_id: userId,
    is_active: true,
  };
  try {
    // V22.9.37 감사 SIM-4: 후보를 만든 최근 3개월 기록을 다시 읽어 지출자·분류를 이어받는다. 규칙은 확정한 사람이 아니라
    // 그 기록을 낸 사람의 것이어야 한다. 원래 지출자가 더는 활성 참여자가 아니면 확정한 사람으로 둔다. 분류는 폼이 기본값
    // (정기지출)을 보냈을 때 기록에서 가장 많이 쓴 분류로 채운다.
    const windowStart = `${addMonthsYm(month, -2)}-01`;
    const windowEnd = nextMonthStart(month);
    const [historyRows, rawMembers] = await Promise.all([
      fetchAdminRowsRange(env, { householdId: selected.id, start: windowStart, end: windowEnd, type: "expense", limit: 6000, complete: false }),
      fetchRawHouseholdMembers(env, selected.id),
    ]);
    const candidateKey = normalizeRecurringKey(row);
    const sourceRows = safeArray(historyRows).filter((item) => normalizeRecurringKey(item) === candidateKey && !["recurring", "recurring_auto"].includes(String(item.source || "")));
    const sourceSpender = mostFrequentValue(sourceRows.map((item) => item.user_id));
    if (sourceSpender && recurringSpenderEligible(rawMembers, sourceSpender)) row.user_id = sourceSpender;
    const sourceCategory = mostFrequentValue(sourceRows.map((item) => item.category));
    if (sourceCategory && row.category === "정기지출") row.category = sourceCategory.slice(0, 80);
    const thisMonth = currentMonthKst();
    const thisMonthInWindow = windowStart <= `${thisMonth}-01` && `${thisMonth}-01` < windowEnd;
    await markRecurringAppliedIfRecordedThisMonth(env, selected.id, row, thisMonthInWindow ? safeArray(historyRows).filter((item) => String(item.transaction_date || "").slice(0, 7) === thisMonth) : null);
    const created = await withHouseholdDatabaseLease(env, selected.id, async ({ assertFresh }) => {
      const existing = await fetchRecurringStrict(env, selected.id);
      const key = normalizeRecurringKey(row);
      if (safeArray(existing).some((item) => normalizeRecurringKey(item) === key)) return false;
      assertFresh();
      await supabase(env, "/rest/v1/accountbook_recurring", {
        method: "POST",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify(row),
      });
      return true;
    });
    return redirectResponse(`${returnTo}&msg=${created ? "recurring_registered" : "recurring_exists"}`);
  } catch (err) {
    rememberOpsEvent({ kind: "recurring_candidate_confirm_failed", severity: "warn", path: "/my/recurring/from-candidate", method: "POST", detail: safeError(err) });
    return redirectResponse(`${returnTo}&err=${isUncertainStorageWrite(err) ? "db_write_unknown" : "recurring_save_failed"}`);
  }
}

// V22.9.76: 정기 항목 분류의 기본값과 수입 분류 선택지. 지출은 예전 기본값("정기지출")을 그대로 쓴다.
// 수입은 빠른 입력·가져오기가 분류를 모를 때 쓰는 "기타수입"이다(미분류로 보여 나중에 고를 수 있다).
const RECURRING_INCOME_CATEGORIES = ["급여", "상여/보너스", "용돈수입", "환급", "이자배당", "부업/매출", "기타수입"];
function defaultRecurringCategory(type = "expense") {
  return String(type) === "income" ? "기타수입" : "정기지출";
}

// 가장 많이 나온 비어 있지 않은 값. 같은 횟수면 먼저 나온 값이다.
function mostFrequentValue(values = []) {
  const counts = Object.create(null);
  for (const value of values) {
    const key = String(value || "").trim();
    if (key) counts[key] = (counts[key] || 0) + 1;
  }
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "";
}

function renderMySettingsHtml({ env, url, user, month, households, selected, rows = [], budgets, budget, customCategories, recurring, budgetReadFailed = false, planFingerprint = "", budgetDraft = null, msg = "", err = "" }) {
  const title = escapeHtml(appName(env));
  const hh = `household_id=${encodeURIComponent(selected.id)}&month=${encodeURIComponent(month)}`;
  const householdOptions = households.map((h) => `<option value="${escapeHtml(h.id)}" data-household-name="${escapeHtml(h.name || "가계부")}"${h.id === selected.id ? " selected" : ""}>${escapeHtml(h.name)} · ${escapeHtml(userHouseholdRoleLabel(h.role || "member"))}</option>`).join("");
  const incomeRows = budgetDraft ? budgetDraftRows(budgetDraft, "income") : incomeBudgetRows(budgets).filter((r) => r.stored || Number(r.amount || 0) > 0);
  while (!budgetDraft && incomeRows.length < 2) incomeRows.push({ name: defaultIncomeBudgetNames()[incomeRows.length] || "기타수입", amount: 0 });
  const expenseAllRows = expenseBudgetRows(budgets, customCategories);
  const expenseSetRows = expenseAllRows.filter((r) => Number(r.amount || 0) > 0);
  const starterNames = ["외식", "교통", "생활용품", "보험", "카페/간식"];
  const savedEditRows = expenseAllRows.filter(row => row.stored);
  const budgetEditRows = budgetDraft ? budgetDraftRows(budgetDraft, "expense") : savedEditRows.length ? savedEditRows : starterNames.map((name) => ({ name, amount: 0 }));
  const incomePlanTotal = budgetCenterSummary(rows, budgets).incomeBudget;
  const expensePlanTotal = sumBudgetAmounts(expenseSetRows);
  const budgetCenter = budgetCenterSummary(rows, budgets);
  const actualIncomeList = budgetCenter.actualIncomeCategories.length
    ? budgetCenter.actualIncomeCategories.map((item) => `<li><span>${escapeHtml(item.category)}</span><b>${numberWithCommas(item.amount)}원</b><small>${numberWithCommas(item.count)}건</small></li>`).join("")
    : `<li class="emptyIncome">아직 이번 달 수입 기록이 없습니다.</li>`;
  const recurringInfo = recurringSummary(recurring);
  const recurringUnavailable = recurring === null;
  const recurringMoney = (value) => recurringUnavailable ? "확인 불가" : `${numberWithCommas(value)}원`;
  const categoryRows = defaultExpenseBudgetNames(customCategories);
  const categoryOptions = [`<option value="">직접입력</option>`, ...categoryRows.map((c) => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`)].join("");
  const incomeOptions = [`<option value="">직접입력</option>`, ...defaultIncomeBudgetNames().map((c) => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`)].join("");
  // V22.9.76: 정기 항목 추가 폼에서 구분을 수입으로 고르면 분류 추천이 수입 분류로 바뀐다(지출 분류만 보였다).
  const recurringIncomeCategoryOptions = RECURRING_INCOME_CATEGORIES.map((c) => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join("");
  const recurringRows = safeArray(recurring).length ? safeArray(recurring).map((r) => `<tr><td data-label="내용">${escapeHtml(r.memo || "")}</td><td data-label="구분">${escapeHtml(r.type === "income" ? "수입" : "지출")}</td><td data-label="금액">${numberWithCommas(r.amount)}원</td><td data-label="분류">${escapeHtml(r.category || "")}</td><td data-label="일자">매월 ${escapeHtml(r.day_of_month || 1)}일</td><td data-label="최근 적용월">${escapeHtml(r.last_applied_month || "-")}</td><td data-label="관리">${renderRecurringEditForm(r, selected.id, month, [], "/my/recurring/save")}<form method="post" action="/my/recurring/delete" onsubmit="return confirm('삭제할까요?')"><input type="hidden" name="household_id" value="${escapeHtml(selected.id)}"/><input type="hidden" name="month" value="${escapeHtml(month)}"/><input type="hidden" name="id" value="${escapeHtml(r.id || "")}"/><button class="danger" type="submit">삭제</button></form></td></tr>`).join("") : recurringUnavailable ? `<tr><td colspan="7" role="status">정기 항목 목록을 불러오지 못했어요. 이미 등록한 항목이 있을 수 있으니 새로고침해 목록을 확인한 뒤 추가해 주세요.</td></tr>` : `<tr><td colspan="7">아직 정기지출이 없습니다.</td></tr>`;
  const incomeInputs = incomeRows.map((r) => `<div class="budgetLine incomeLine"><input name="income_name" value="${escapeHtml(r.name)}" placeholder="직접입력: 수입 종류"/><select class="pickValue">${incomeOptions}</select><input name="income_amount" value="${escapeHtml(typeof r.amount === "number" ? String(r.amount || "") : String(r.amount ?? ""))}" inputmode="numeric" placeholder="예상 수입"/></div>`).join("");
  // V22.9.26: 설정한 분류를 모두 그린다. 12행만 그리면 저장(월 전체 교체)이 13번째부터 지웠다.
  const expenseInputs = budgetEditRows.map((r) => `<div class="budgetLine expenseLine"><input name="budget_category" value="${escapeHtml(r.name)}" placeholder="직접입력: 예산 분류"/><select class="pickValue">${categoryOptions}</select><input name="budget_amount" value="${escapeHtml(typeof r.amount === "number" ? String(r.amount || "") : String(r.amount ?? ""))}" inputmode="numeric" placeholder="예산 금액"/></div>`).join("");
  const budgetListRows = expenseSetRows.length ? expenseSetRows.map((r) => {
    const spent = Number(budget.categoryAlerts.find(item => normalizeText(item.category) === normalizeText(r.name))?.spent || 0);
    const remain = Math.max(0, Number(r.amount || 0) - spent);
    const rate = Number(r.amount || 0) ? Math.round(spent / Number(r.amount || 0) * 100) : 0;
    return `<tr><td><b>${escapeHtml(r.name)}</b></td><td>${numberWithCommas(r.amount)}원</td><td>${numberWithCommas(spent)}원</td><td>${numberWithCommas(remain)}원</td><td>${rate}%</td></tr>`;
  }).join("") : `<tr><td colspan="5">아직 저장된 분류별 예산이 없습니다. 필요한 분류만 추가해서 저장하세요.</td></tr>`;
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><title>${title} · 설정</title><style>${myNavCss()}${moneyPlanTabsCss()}*,*:before,*:after{box-sizing:border-box}html,body{max-width:100%;overflow-x:hidden}body{margin:0;background:linear-gradient(180deg,#fff9d9,#f8fafc 50%,#eef2f7);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans KR",sans-serif;color:#101828;letter-spacing:-.025em}.wrap{max-width:1240px;margin:0 auto;padding:16px 16px 120px}.hero,.card{background:#fff;border:1px solid #e8edf4;border-radius:24px;padding:20px;margin:14px 0;box-shadow:0 12px 30px rgba(15,23,42,.06)}.hero p,.muted{color:#667085;line-height:1.55;font-size:13px}.summaryGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.summaryBox{background:#f8fafc;border:1px solid #e8edf4;border-radius:18px;padding:14px;min-width:0}.summaryBox b{display:block;font-size:22px;overflow-wrap:anywhere}.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.rowform{display:grid;grid-template-columns:100px 1fr 150px 150px 150px 100px auto;gap:8px;align-items:center}.rowform input,.rowform select{min-width:0;width:100%}.budgetForm{display:grid;grid-template-columns:1fr 1fr;gap:14px}.budgetLine{display:grid;grid-template-columns:1.2fr .9fr 150px;gap:8px;margin:8px 0}.budgetLine>*{min-width:0}.incomeSummary{list-style:none;padding:0;margin:10px 0;display:grid;gap:7px}.incomeSummary li{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;align-items:center;border:1px solid #e8edf4;border-radius:13px;padding:10px 12px}.incomeSummary li span{font-weight:900}.incomeSummary li small{color:#667085}.incomeSummary .emptyIncome{display:block;color:#667085;background:#f8fafc}input,select{border:1px solid #cbd5e1;border-radius:14px;padding:11px;font:inherit;background:#fff}button,.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:14px;background:#111827;color:#fff!important;padding:11px 14px;text-decoration:none;font-weight:1000;cursor:pointer}.secondary{background:#eef2f7!important;color:#111827!important;border:1px solid #d8dee8}.danger{background:#ef4444!important}.ok{background:#ecfdf5;color:#166534;border:1px solid #bbf7d0;border-radius:14px;padding:11px}.error{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca;border-radius:14px;padding:11px}table{width:100%;border-collapse:collapse;background:#fff}td,th{border-bottom:1px solid #e8edf4;padding:10px;text-align:left;font-size:13px}.scroll{overflow:auto;border:1px solid #e8edf4;border-radius:18px}details.fold{border:1px solid #e8edf4;border-radius:22px;background:#fff;padding:6px 14px}details.fold summary{cursor:pointer;font-weight:1000;padding:12px 4px}.sectionNote{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;border-radius:16px;padding:12px;font-size:13px;line-height:1.55}.keywordGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.keywordCard{display:grid;grid-template-columns:110px 1fr auto;gap:8px;align-items:center;border:1px solid #e8edf4;border-radius:16px;padding:10px;background:#f8fafc}.keywordCard label{font-weight:1000}.addBtn{background:#eef2ff!important;color:#3730a3!important;border:1px solid #c7d2fe}@media(max-width:900px){.budgetForm,.keywordGrid{grid-template-columns:1fr}.budgetLine,.keywordCard,.rowform{grid-template-columns:1fr}.toolbar>*{width:100%}}@media(max-width:600px){.wrap{padding:10px 10px 126px}.hero,.card{padding:16px;border-radius:19px}.summaryGrid{grid-template-columns:1fr 1fr}.summaryBox b{font-size:19px}.incomeSummary li{grid-template-columns:1fr auto}.incomeSummary li small{grid-column:1/-1}.budgetLine input,.budgetLine select{width:100%;font-size:16px}}@media(max-width:360px){.summaryGrid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="appLayout">${renderMySideNav(selected, selected.role, month, "settings")}<div class="pageMain">${renderMoneyPlanTabs("settings", { month, householdId: selected.id })}<section class="hero"><h1>설정 한눈에</h1><p>이번 달 요약과 예산·정기 설정을 한 화면에서 봅니다. 각 항목은 위 탭에서 더 자세히 볼 수 있습니다. 실제 수입은 기록에서 자동 합산하고, 예상 수입과 지출 한도는 종류·분류별 행의 합계로 계산합니다.</p></section>${msg ? `<div class="ok">${budgetPlanMessage(msg) || formatMessage(msg)}</div>` : ""}${err ? `<div class="error">${budgetPlanMessage(err) || formatMessage(err)}</div>` : ""}<section class="card"><form method="get" action="/my/settings" class="toolbar"><select name="household_id">${householdOptions}</select><input type="month" name="month" value="${escapeHtml(month)}"/><button type="submit">조회</button><a class="btn secondary" href="/app?${hh}">홈</a></form></section><section class="card"><h2>이번 달 요약</h2><div class="summaryGrid"><div class="summaryBox"><span class="muted">실제 수입 · 기록 자동합계</span><b>${numberWithCommas(budgetCenter.actualIncome)}원</b></div><div class="summaryBox"><span class="muted">예상 수입 · 종류별 합계</span><b>${numberWithCommas(incomePlanTotal)}원</b></div><div class="summaryBox"><span class="muted">지출 예산 · 분류별 합계</span><b>${numberWithCommas(expensePlanTotal)}원</b></div><div class="summaryBox"><span class="muted">이번 달 지출</span><b>${numberWithCommas(budget.expense || 0)}원</b><span class="muted">예산 사용 ${budget.rate || 0}%</span></div></div><h3>실제 수입 분류</h3><ul class="incomeSummary">${actualIncomeList}</ul></section><section class="card"><h2>예상 수입 + 지출 예산</h2><p class="muted">월 총액을 따로 입력하지 않습니다. 수입 종류와 지출 분류별 금액을 고치면 저장 전 미리보기를 계산합니다. 위 요약은 저장된 계획입니다. 빈 행과 0원 행은 저장하지 않습니다.</p>${budgetReadFailed && !budgetDraft ? `<p class="error" role="alert">예산을 불러오지 못해 지금은 편집할 수 없습니다. 저장된 예산은 그대로이니 잠시 뒤 새로고침해 주세요.</p>` : `<form method="post" action="/my/budget-bulk/save" id="budgetBulkForm"><input type="hidden" name="household_id" value="${escapeHtml(selected.id)}"/><input type="hidden" name="month" value="${escapeHtml(month)}"/><input type="hidden" name="plan_fingerprint" value="${escapeHtml(budgetDraft ? budgetDraft.fingerprint : planFingerprint)}"/><div class="budgetForm"><div><h3>예상 수입 종류</h3><div id="incomeRows">${incomeInputs}</div><p><button type="button" class="addBtn" data-add="income">+ 수입 종류 추가</button></p><div class="sectionNote">급여·부수입을 고르거나 왼쪽 칸에 직접 이름을 입력하세요. 입력한 행의 합계가 예상 수입입니다.</div></div><div><h3>지출 분류별 한도</h3><div id="expenseRows">${expenseInputs}</div><p><button type="button" class="addBtn" data-add="expense">+ 지출 분류 추가</button></p><div class="sectionNote">외식·교통 등 필요한 분류만 입력하세요. 분류별 합계가 이번 달 전체 지출 예산입니다.</div></div></div>${renderBudgetPlanPreview(incomeRows, budgetEditRows, budgets, budgetDraft?.error || "", "/my/settings?" + hh)}<p><button type="submit">종류별 수입·분류별 예산 저장</button></p></form>`}</section><section class="card"><h2>저장된 분류별 지출 예산</h2><p class="muted">상위·하위 예산의 행별 사용액은 겹칠 수 있습니다. 전체 사용액은 거래마다 한 번만 계산합니다. 분류별 배분 합계: <b>${numberWithCommas(expensePlanTotal)}원</b></p><div class="scroll"><table><thead><tr><th>분류</th><th>예산</th><th>사용</th><th>남음</th><th>사용률</th></tr></thead><tbody>${budgetListRows}</tbody></table></div></section><section class="card"><h2>정기 수입·지출 자동 기록</h2><div class="summaryGrid"><div class="summaryBox"><span class="muted">정기지출 합계</span><b>${recurringMoney(recurringInfo.expense)}</b></div><div class="summaryBox"><span class="muted">정기수입 합계</span><b>${recurringMoney(recurringInfo.income)}</b></div><div class="summaryBox"><span class="muted">월 순정기액</span><b>${recurringMoney(recurringInfo.net)}</b></div><div class="summaryBox"><span class="muted">등록 건수</span><b>${recurringUnavailable ? "확인 불가" : `${numberWithCommas(recurringInfo.count)}건`}</b></div></div><form method="post" action="/my/recurring/save" class="rowform"><input type="hidden" name="household_id" value="${escapeHtml(selected.id)}"/><input type="hidden" name="month" value="${escapeHtml(month)}"/><select name="type" onchange="var c=this.form&&this.form.elements.category;if(c)c.setAttribute('list',this.value==='income'?'settingsIncomeCategoryList':'settingsCategoryList')"><option value="expense">지출</option><option value="income">수입</option></select><input name="memo" placeholder="예: 자동차보험" required/><input name="amount" placeholder="금액" required/><input name="category" list="settingsCategoryList" placeholder="분류"/><datalist id="settingsCategoryList">${categoryOptions}</datalist><datalist id="settingsIncomeCategoryList">${recurringIncomeCategoryOptions}</datalist><input name="payment_method" placeholder="결제수단"/><input name="day_of_month" type="number" min="1" max="31" value="1"/><button type="submit">정기항목 저장</button></form><div class="scroll" style="margin-top:14px"><table class="ab38Recurring"><thead><tr><th>내용</th><th>구분</th><th>금액</th><th>분류</th><th>일자</th><th>최근 적용월</th><th></th></tr></thead><tbody>${recurringRows}</tbody></table></div></section><section class="card"><h2>분류·키워드</h2><p class="muted">가족이 실제로 쓰는 표현을 수입·지출 분류에 연결하는 화면은 <b>관리 &gt; 분류·키워드</b> 한 곳에만 둡니다. 같은 편집기를 두 곳에서 열면 어느 쪽이 최신인지 헷갈립니다.</p><p><a class="btn secondary" href="/keyword-guide?${hh}">분류·키워드 관리 열기</a></p></section></div></div></main></body></html>`;
}
function myReturnLocation(month = currentMonthKst(), householdId = "", extra = {}) {
  const qs = new URLSearchParams();
  qs.set("month", validMonth(month) || currentMonthKst());
  if (householdId) qs.set("household_id", householdId);
  for (const [k, v] of Object.entries(extra || {})) if (v !== undefined && v !== null && String(v) !== "") qs.set(k, String(v));
  return `/my?${qs.toString()}#records`;
}

function canWriteMyHousehold(role = "") {
  const r = String(role || "").toLowerCase();
  return ["owner", "admin", "member"].includes(r);
}

function canReadMyHousehold(role = "") {
  return ["owner", "admin", "member", "viewer"].includes(String(role || "").toLowerCase());
}

function canManageMyHousehold(role = "") {
  return ["owner", "admin"].includes(String(role || "").toLowerCase());
}

function householdAccessTitle(role = "") {
  if (role === "pending") return "참여 승인 대기 중";
  if (role === "blocked") return "이 가계부의 이용이 제한됨";
  return "이 화면은 관리자 전용";
}

// V22.9.79 감사 V44 F-6: 소유자·관리자 전용 화면의 안내는 화면마다 다르게 말한다. 예전에는 ‘참여자·초대 및 단톡방 연결’ 이야기 하나로
// 수입·예산 화면까지 안내해, 예산 설정 링크를 누른 구성원이 다른 화면 이야기를 읽었다. screen 은 부르는 쪽이 정한 고정 이름이다.
// extra 는 지금 권한으로 열 수 있는 가까운 화면으로 가는 단추다.
function manageOnlyGuide(screen = "", { month = currentMonthKst(), householdId = "" } = {}) {
  const hh = householdId ? `&household_id=${encodeURIComponent(householdId)}` : "";
  if (screen === "settings") {
    return {
      guide: "수입 계획·분류별 예산·정기지출·분류 키워드를 바꾸는 화면은 소유자 또는 관리자만 열 수 있습니다. 지금 권한으로는 예산 현황을 볼 수 있어요.",
      steps: ["예산 현황 보기에서 예산과 사용 상태 확인", "예산이나 정기지출을 바꾸고 싶다면 소유자 또는 관리자에게 요청", "자주 바꿔야 한다면 소유자에게 관리자 권한 요청"],
      extra: { href: `/budgets?month=${encodeURIComponent(month)}${hh}`, label: "예산 현황 보기" },
    };
  }
  if (screen === "members") {
    return {
      guide: "참여자 목록과 초대코드는 소유자 또는 관리자만 볼 수 있습니다. 지금 권한으로 열 수 있는 화면(홈·기록·예산·분석)은 계속 사용할 수 있어요.",
      steps: ["내 가계부로 돌아가기", "참여자를 초대하거나 권한을 바꾸려면 소유자 또는 관리자에게 요청", "관리 작업을 직접 해야 한다면 소유자에게 관리자 권한 요청"],
    };
  }
  if (screen === "groups") {
    return {
      guide: "카카오 단톡방 연결은 소유자 또는 관리자만 할 수 있습니다. 지금 권한으로 열 수 있는 화면(홈·기록·예산·분석)은 계속 사용할 수 있어요.",
      steps: ["내 가계부로 돌아가기", "단톡방을 연결하거나 바꾸려면 소유자 또는 관리자에게 요청", "관리 작업을 직접 해야 한다면 소유자에게 관리자 권한 요청"],
    };
  }
  return {
    guide: "이 화면은 소유자 또는 관리자만 열 수 있습니다. 지금 권한으로 열 수 있는 화면은 계속 사용할 수 있어요.",
    steps: ["내 가계부로 돌아가기", "바꿀 내용이 있으면 소유자 또는 관리자에게 요청", "계속 필요하다면 소유자에게 관리자 권한 요청"],
  };
}

function renderMyAccessStatusHtml({ env, user = null, household = null, role = "", month = currentMonthKst(), manageOnly = false, screen = "" }) {
  const normalizedRole = String(role || household?.role || "").toLowerCase();
  const manageGuide = manageOnly ? manageOnlyGuide(screen, { month, householdId: household?.id || "" }) : null;
  const title = manageOnly && canReadMyHousehold(normalizedRole) ? "관리자 권한이 필요한 화면" : householdAccessTitle(normalizedRole);
  let guide = "가계부 목록에서 이용 가능한 가계부를 선택하거나 새 가계부를 만들어 주세요.";
  let steps = ["가계부 전환·추가 화면으로 이동", "이용 가능한 가계부 선택", "문제가 계속되면 가계부 관리자에게 권한 확인 요청"];
  if (normalizedRole === "pending") {
    guide = "참여 요청은 정상 접수됐습니다. 같은 코드를 반복 입력해도 승인이 빨라지지 않으며, 관리자가 승인하면 기록과 조회가 열립니다.";
    steps = ["가계부 관리자에게 참여 승인 요청", "승인 전에는 다른 이용 가능한 가계부 사용", "승인 후 가계부 목록에서 다시 열기"];
  } else if (normalizedRole === "blocked") {
    guide = "초대코드를 다시 입력해도 제한은 해제되지 않습니다. 가계부 관리자만 권한을 변경할 수 있습니다.";
    steps = ["가계부 관리자에게 제한 사유와 권한 확인 요청", "다른 이용 가능한 가계부로 전환", "필요하면 별도의 새 가계부 생성"];
  } else if (manageOnly) {
    guide = manageGuide.guide;
    steps = manageGuide.steps;
  }
  const householdName = household?.name || "선택한 가계부";
  const list = steps.map((step, index) => `<li><b>${index + 1}</b><span>${escapeHtml(step)}</span></li>`).join("");
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><meta name="robots" content="noindex,nofollow"/><title>${escapeHtml(appName(env))} · ${escapeHtml(title)}</title><style>${MY_ACCESS_STATUS_CSS}</style></head><body><main class="wrap"><section class="card"><span class="badge">${escapeHtml(userHouseholdRoleLabel(normalizedRole || "member"))}</span><h1>${escapeHtml(title)}</h1><p class="sub"><b>${escapeHtml(householdName)}</b><br/>${escapeHtml(user?.nickname || "사용자")}님의 현재 권한을 기준으로 안전하게 접근을 제한했습니다.</p><div class="guide">${escapeHtml(guide)}</div><ol>${list}</ol><div class="actions">${manageGuide?.extra && canReadMyHousehold(normalizedRole) ? `<a class="btn" href="${escapeHtml(manageGuide.extra.href)}">${escapeHtml(manageGuide.extra.label)}</a>` : ""}<a class="${manageGuide?.extra && canReadMyHousehold(normalizedRole) ? "btn soft" : "btn"}" href="/my/households">가계부 전환·추가</a>${canReadMyHousehold(normalizedRole) ? `<a class="btn soft" href="/app?month=${encodeURIComponent(month)}&household_id=${encodeURIComponent(household?.id || "")}">내 가계부</a>` : `<a class="btn soft" href="/my">처음 화면</a>`}</div></section></main></body></html>`;
}

const MY_ACCESS_STATUS_CSS = `*,*:before,*:after{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#fff7ed,#f8fafc 50%);color:#111827;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans KR",sans-serif}.wrap{max-width:760px;margin:0 auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:28px;padding:24px;margin:14px 0;box-shadow:0 18px 44px rgba(15,23,42,.08)}.badge{display:inline-flex;border-radius:999px;background:#fff7ed;color:#9a3412;border:1px solid #fed7aa;padding:6px 10px;font-size:12px;font-weight:1000}h1{font-size:28px;margin:14px 0 8px}.sub{color:#64748b;line-height:1.65}.guide{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;border-radius:18px;padding:14px;line-height:1.65}ol{list-style:none;padding:0;margin:18px 0;display:grid;gap:10px}li{display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:center;border:1px solid #e5e7eb;border-radius:16px;padding:11px}li b{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#111827;color:#fff}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;border-radius:14px;background:#111827;color:#fff;text-decoration:none;font-weight:1000;padding:0 14px}.soft{background:#eef2f7;color:#111827}@media(max-width:620px){.wrap{padding:12px}.card{padding:19px;border-radius:22px}h1{font-size:24px}.actions,.btn{width:100%}}`;

// V22.9.37 감사 H9: 주소의 가계부가 없거나 참여하지 않은 가계부이면 첫 가계부로 바꿔 그리지 않고 이 화면을 낸다(404).
// 기준선: "사용자가 명시한 household_id 가 접근 가능한 가계부가 아니면 첫 가계부로 대체하지 않고 요청을 거부한다."
function renderHouseholdNotFoundHtml({ env, user = null, requestedId = "", listHref = "/my/households" } = {}) {
  const title = "가계부를 찾을 수 없어요";
  const guide = "주소에 적힌 가계부가 삭제되었거나 내가 참여하지 않은 가계부입니다. 다른 가계부로 바꿔 보여 주지 않았습니다.";
  const steps = ["가계부 목록에서 쓸 가계부를 다시 선택", "초대받은 가계부라면 초대코드로 참여 요청", "주소를 저장해 두었다면 새 주소로 다시 저장"];
  const list = steps.map((step, index) => `<li><b>${index + 1}</b><span>${escapeHtml(step)}</span></li>`).join("");
  const safeId = String(requestedId || "").slice(0, 80);
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><meta name="robots" content="noindex,nofollow"/><title>${escapeHtml(appName(env))} · ${title}</title><style>${MY_ACCESS_STATUS_CSS}</style></head><body><main class="wrap"><section class="card"><span class="badge">찾을 수 없음</span><h1>${title}</h1><p class="sub">${safeId ? `<b>요청한 가계부 ID: ${escapeHtml(safeId)}</b><br/>` : ""}${escapeHtml(user?.nickname || "사용자")}님이 볼 수 있는 가계부 중에 이 가계부가 없습니다.</p><div class="guide">${escapeHtml(guide)}</div><ol>${list}</ol><div class="actions"><a class="btn" href="${escapeHtml(listHref)}">가계부 목록으로</a><a class="btn soft" href="/my">처음 화면</a></div></section></main></body></html>`;
}

function householdNotFoundResponse(args = {}) {
  return htmlResponse(renderHouseholdNotFoundHtml(args), 404);
}

function myAccessStatusResponse(args = {}, status = 403) {
  return htmlResponse(renderMyAccessStatusHtml(args), status);
}

function canManageMyRecord(role = "", row = {}, userId = "") {
  const r = String(role || "").toLowerCase();
  if (["owner", "admin"].includes(r)) return true;
  return canWriteMyHousehold(r) && String(row.user_id || "") === String(userId || "");
}

// V22.9.43: 소유자가 가계부마다 정하는 구성원 권한. 값이 없으면 기록·수정(구성원이 자기 기록을 고치고 지운다,
// V22.9.42까지와 같다)이다. 기록만이면 구성원은 새 기록만 더하고, 수정·삭제·복구와 공동 설정 변경은 소유자·관리자가 한다.
// DB 역할 값(household_members.role)은 바꾸지 않는다. 역할 제약(V22.8.46) 밖의 새 역할을 만들지 않기 위해서다.
const MEMBER_POLICY_RECORD_ONLY = "record_only";
const MEMBER_POLICY_RECORD_EDIT = "record_edit";

function memberPolicySettingsKey(householdId = "") {
  return `household_member_policy_v22943:${String(householdId || "").trim()}`;
}

function parseMemberPolicyValue(value) {
  const item = parseStrictSettingsObject(value, "household_member_policy");
  if (!Object.keys(item).length) return MEMBER_POLICY_RECORD_EDIT;
  if (item.version !== 1 || ![MEMBER_POLICY_RECORD_ONLY, MEMBER_POLICY_RECORD_EDIT].includes(item.mode)) throw settingsDataError("household_member_policy", "invalid_shape");
  return item.mode;
}

// 읽기 실패와 모양이 틀린 값은 오류로 올린다. 부르는 쪽이 허용으로 넘어가지 않고 거절(막힌 쪽)로 처리한다.
async function fetchHouseholdMemberPolicy(env, householdId = "") {
  const hid = String(householdId || "").trim();
  if (!hid) throw new Error("household_id_required");
  const cache = env?.__AB_MEMBER_POLICY instanceof Map ? env.__AB_MEMBER_POLICY : null;
  if (cache?.has(hid)) return cache.get(hid);
  const mode = parseMemberPolicyValue(await getSettingValueStrict(env, memberPolicySettingsKey(hid)));
  cache?.set(hid, mode);
  return mode;
}

// 기록을 고치고 지우는 권한(자기 기록 기준은 canManageMyRecord 가 따로 본다). 소유자·관리자는 정책과 무관하고,
// 조회 전용·승인 대기·이용 제한은 원래부터 막혀 있다. 구성원만 정책을 한 번 읽는다.
async function canChangeMyHouseholdRecords(env, role = "", householdId = "") {
  const r = String(role || "").toLowerCase();
  if (["owner", "admin"].includes(r)) return true;
  if (r !== "member") return false;
  return (await fetchHouseholdMemberPolicy(env, householdId)) !== MEMBER_POLICY_RECORD_ONLY;
}

// 홈 화면이 다른 설정과 함께 한 번에 읽은 값을 풀 때 쓴다. 깨진 값은 ‘기록만’으로 보고 단추를 숨긴다.
function homeMemberPolicyValue(value) {
  try { return parseMemberPolicyValue(value); } catch (_) { return MEMBER_POLICY_RECORD_ONLY; }
}

// 화면에서 수정·삭제 단추를 보일지 정할 때만 쓴다. 읽지 못하면 단추를 숨긴다(서버 경로는 따로 다시 확인한다).
async function canChangeMyHouseholdRecordsForView(env, role = "", householdId = "") {
  try { return await canChangeMyHouseholdRecords(env, role, householdId); }
  catch (_) { return false; }
}

function memberPolicyLabel(mode = "") {
  return mode === MEMBER_POLICY_RECORD_ONLY ? "기록만" : "기록·수정";
}

function memberPolicyDescription(mode = "") {
  return mode === MEMBER_POLICY_RECORD_ONLY
    ? "구성원은 새 기록만 남기고, 수정·삭제는 소유자·관리자가 해요."
    : "구성원은 기록하고, 자기가 쓴 기록을 고치거나 지울 수 있어요.";
}

function memberRecordChangeMessage(code = "") {
  return code === "member_policy_unavailable"
    ? "구성원 권한을 확인하지 못해 기록을 바꾸지 않았습니다. 잠시 후 다시 시도하세요."
    : "소유자가 구성원 권한을 ‘기록만’으로 정해 기록을 수정·삭제할 수 없습니다. 소유자나 관리자에게 요청하세요.";
}

// 기록을 고치거나 지우는 웹·API 경로가 쓰는 판정. ""이면 허용, 아니면 화면 오류 코드다.
async function memberRecordChangeError(env, role = "", householdId = "") {
  try { return (await canChangeMyHouseholdRecords(env, role, householdId)) ? "" : "member_record_only"; }
  catch (_) { return "member_policy_unavailable"; }
}

// 소유자만 바꾼다. 가계부 잠금 안에서 역할을 다시 엄격하게 읽고 쓰며, 삭제된 가계부에는 쓰지 않는다.
// 저장된 값이 깨져 있으면 소유자가 고른 새 값으로 덮어 고친다.
async function saveHouseholdMemberPolicy(env, householdId = "", actorUserId = "", mode = "") {
  const hid = String(householdId || "").trim();
  const actor = String(actorUserId || "").trim();
  if (!hid || !actor || ![MEMBER_POLICY_RECORD_ONLY, MEMBER_POLICY_RECORD_EDIT].includes(mode)) return { ok: false, error: "member_policy_invalid" };
  return withHouseholdSettingsRmw(env, hid, async ({ assertFresh }) => {
    const rows = await supabase(env, `/rest/v1/household_members?household_id=eq.${encodeURIComponent(hid)}&user_id=eq.${encodeURIComponent(actor)}&select=role`, { method: "GET" });
    if (!Array.isArray(rows)) throw new Error("member_policy_role_source_invalid");
    if (bestRoleFromRows(rows) !== "owner") return { ok: false, error: "member_policy_owner_only" };
    const key = memberPolicySettingsKey(hid);
    let current = "";
    try { current = parseMemberPolicyValue(await getSettingValueStrict(env, key)); } catch (err) { if (err?.code !== "settings_data_invalid") throw err; }
    if (current !== mode) {
      assertFresh();
      await saveSettingValue(env, key, JSON.stringify({ version: 1, mode, updated_by: actor, updated_at: new Date().toISOString() }));
    }
    if (env?.__AB_MEMBER_POLICY instanceof Map) env.__AB_MEMBER_POLICY.set(hid, mode);
    return { ok: true, mode, unchanged: current === mode };
  }, { missingHousehold: "noop", missingResult: { ok: false, error: "member_policy_household_missing" } });
}

function memberRecordOnlyRefusalText(householdName = "") {
  return `‘${householdName || "이 가계부"}’는 소유자가 구성원 권한을 ‘기록만’으로 정해 기록을 고치거나 지울 수 없어요. 고칠 내용은 소유자나 관리자에게 알려 주세요.`;
}

function memberPolicyJoinLine(mode = "") {
  return mode === MEMBER_POLICY_RECORD_ONLY
    ? "내 권한: 기록만 (수정·삭제는 소유자·관리자가 해요)"
    : "내 권한: 기록·수정 (내가 쓴 기록은 고치고 지울 수 있어요)";
}

// V22.9.63 감사(웹 2): 라우터가 기억 쿠키(ab_hh)로 채운 household_id 는 사용자가 직접 적은 것이 아니다(config-readiness.js).
function householdIdWasRemembered(request) {
  try { return String(request?.headers?.get("x-ab-household-memory") || "") === "1"; } catch (_) { return false; }
}

async function getMySelectedHousehold(env, userId, householdId = "") {
  const memberships = await fetchUserHouseholds(env, userId);
  const households = memberships.filter((h) => canReadMyHousehold(h.role));
  const requestedId = String(householdId || "").trim();
  if (!memberships.length) return { households, memberships, selected: null, restricted: null, invalidRequested: requestedId };
  const requested = requestedId ? memberships.find((h) => String(h.id) === requestedId) || null : null;
  if (requestedId && !requested) return { households, memberships, selected: null, restricted: null, invalidRequested: requestedId };
  if (requested && !canReadMyHousehold(requested.role)) return { households, memberships, selected: null, restricted: requested, invalidRequested: "" };
  if (!households.length) return { households, memberships, selected: null, restricted: requested || memberships[0] || null, invalidRequested: "" };
  const selected = (requested && canReadMyHousehold(requested.role) ? requested : null) || households[0] || null;
  return { households, memberships, selected, restricted: null, invalidRequested: "" };
}

function transactionEditHistoryKey(householdId = "") {
  return `transaction_edit_history:${String(householdId || "default").trim() || "default"}`;
}

// 표시용 수정 이력은 가계부마다 설정 JSON 하나에 모인다. 읽기 실패나 깨진 JSON 을 빈 값으로 보고 새 항목만
// 저장하면 가계부 전체의 이력이 사라진다(QA B06). 그래서 잠금 안에서 엄격하게 읽어 병합하고, 읽지 못하면
// 쓰지 않는다. 거래 수정 자체는 이미 원자적 RPC 와 DB 감사에 반영됐으므로 호출부가 이력 실패만 따로 기록한다.
async function fetchTransactionEditHistoryMap(env, householdId = "") {
  const parsed = parseStrictSettingsObject(await getSettingValueStrict(env, transactionEditHistoryKey(householdId)), "transaction_edit_history");
  const out = Object.create(null);
  for (const [id, list] of Object.entries(parsed)) {
    if (id && Array.isArray(list)) out[id] = list.slice(-20);
  }
  return out;
}

function transactionAuditFields() {
  return [
    ["user_id", "지출자"],
    ["type", "구분"],
    ["transaction_date", "날짜"],
    ["amount", "금액"],
    ["memo", "내용"],
    ["category", "분류"],
    ["payment_method", "결제수단"],
  ];
}

function valueForAudit(row = {}, key = "", memberMap = {}) {
  if (key === "user_id") return memberMap[String(row.user_id || "")] || row.user_id || "미지정";
  if (key === "type") return row.type === "income" ? "수입" : "지출";
  if (key === "amount") return `${Number(row.amount || 0).toLocaleString("ko-KR")}원`;
  return String(row[key] ?? "");
}

function buildTransactionChanges(before = {}, after = {}, memberMap = {}) {
  const changes = [];
  for (const [key, label] of transactionAuditFields()) {
    const bRaw = key === "amount" ? Math.round(Number(before[key] || 0)) : String(before[key] ?? "");
    const aRaw = key === "amount" ? Math.round(Number(after[key] || 0)) : String(after[key] ?? "");
    if (String(bRaw) === String(aRaw)) continue;
    changes.push({ field: key, label, before: valueForAudit(before, key, memberMap), after: valueForAudit(after, key, memberMap) });
  }
  return changes;
}

async function appendTransactionEditHistory(env, householdId = "", transactionId = "", before = {}, after = {}, editedBy = "", members = []) {
  if (!householdId || !transactionId) return [];
  const memberMap = memberNameMap(members || []);
  const changes = buildTransactionChanges(before, after, memberMap);
  if (!changes.length) return [];
  return withHouseholdSettingsRmw(env, householdId, async ({ assertFresh }) => {
    const map = await fetchTransactionEditHistoryMap(env, householdId);
    const list = Array.isArray(map[transactionId]) ? map[transactionId] : [];
    list.push({ at: new Date().toISOString(), edited_by: editedBy || "", edited_by_name: memberMap[String(editedBy || "")] || "", changes });
    map[transactionId] = list.slice(-20);
    assertFresh();
    await supabase(env, "/rest/v1/accountbook_settings?on_conflict=key", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify({ key: transactionEditHistoryKey(householdId), value: JSON.stringify(map) }),
    });
    return map[transactionId];
  });
}

function memberExists(members = [], userId = "") {
  return safeArray(members).some((m) => String(m.user_id || "") === String(userId || ""));
}

function memberCanBeSpender(member = {}) {
  return !!String(member?.user_id || "").trim() && !["pending", "blocked"].includes(String(member?.role || "member").toLowerCase());
}

function activeSpenderExists(members = [], userId = "") {
  return safeArray(members).some((member) => memberCanBeSpender(member) && String(member.user_id || "") === String(userId || ""));
}

function canManageAllRecords(role = "") {
  return ["owner", "admin"].includes(String(role || ""));
}

async function getTransactionForUserEdit(env, id, householdId) {
  if (!id || !householdId) return null;
  const params = new URLSearchParams();
  params.set("select", "id,household_id,user_id,type,amount,category,memo,payment_method,transaction_date,source,raw_text,created_at");
  params.set("id", `eq.${id}`);
  params.set("household_id", `eq.${householdId}`);
  params.set("limit", "1");
  const rows = await supabase(env, `/rest/v1/transactions?${params.toString()}`, { method: "GET" }) || [];
  return rows[0] || null;
}

function parseMyAmount(form) {
  return parseFormAmountValue(form.get("amount"));
}

async function handleMyAddTransaction(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const householdId = String(form.get("household_id") || "").trim();
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected) return redirectResponse("/my?err=no_household");
  if (!canWriteMyHousehold(selected.role)) return redirectResponse(myReturnLocation(month, selected.id, { err: "write_not_allowed" }));
  const type = normalizeTransactionType(String(form.get("type") || "expense"));
  const transactionDate = String(form.get("transaction_date") || formatDate(nowKstDate())).trim();
  const amount = parseMyAmount(form);
  if (!amount || amount <= 0) return redirectResponse(myReturnLocation(month, selected.id, { err: "amount_required" }));
  if (amount > MAX_TRANSACTION_AMOUNT) return redirectResponse(myReturnLocation(month, selected.id, { err: "amount_too_large" }));
  if (!isValidTransactionDateString(transactionDate)) return redirectResponse(myReturnLocation(month, selected.id, { err: "invalid_date" }));
  const members = await fetchHouseholdMembers(env, selected.id);
  const requestedUserId = String(form.get("user_id") || "").trim();
  if (requestedUserId && !activeSpenderExists(members, requestedUserId)) return redirectResponse(myReturnLocation(month, selected.id, { err: "spender_not_member" }));
  const spenderUserId = canManageAllRecords(selected.role) && requestedUserId && activeSpenderExists(members, requestedUserId) ? requestedUserId : userId;
  const rawText = String(form.get("raw_text") || "").trim();
  const memoText = String(form.get("memo") || "").trim();
  const manualClass = await resolveManualInputClassification(env, selected.id, type, {
    raw_text: rawText,
    memo: memoText,
    category: String(form.get("category") || "").trim(),
    payment_method: String(form.get("payment_method") || "").trim(),
    manual_category: form.get("quick_manual_category") === "1",
    manual_payment: form.get("quick_manual_payment") === "1",
    // V22.9.80 T-18: 빠른 입력이 문장에서 채운 메모("0")는 분류 판정에 다시 넣지 않는다(표식이 없으면 예전처럼 넣는다).
    manual_memo: form.get("quick_manual_memo") === null ? undefined : form.get("quick_manual_memo") === "1",
  });
  const body = {
    household_id: selected.id,
    user_id: spenderUserId,
    type,
    transaction_date: transactionDate,
    amount,
    memo: memoText,
    category: manualClass.category,
    payment_method: manualClass.payment_method,
    source: "my_web",
    raw_text: rawText,
  };
  try {
    const created = await createManualTransaction(env, body, { requestId: String(form.get("request_id") || ""), preserveEmptyCategory: form.get("quick_manual_category") === "1" && manualClass.category === "", autoMemo: form.get("quick_manual_memo") === "0" && rawText !== "" });
    if (created?.__duplicate_skipped) {
      return redirectResponse(duplicateSkippedReturnLocation(String(transactionDate).slice(0, 7) || month, selected.id));
    }
    return redirectResponse(myReturnLocation(String(transactionDate).slice(0, 7) || month, selected.id, { msg: "created" }));
  } catch (err) {
    rememberOpsEvent({ kind: "save_error", severity: isDatabaseBusyError(err) ? "warn" : "error", path: "/my/transactions", method: "POST", detail: safeError(err) });
    return redirectResponse(myReturnLocation(month, selected.id, { err: userSafeErrorCode(err) }));
  }
}

async function handleMyUpdateTransaction(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const id = String(form.get("id") || "").trim();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const householdId = String(form.get("household_id") || "").trim();
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected) return redirectResponse("/my?err=no_household");
  if (!canWriteMyHousehold(selected.role)) return redirectResponse(myReturnLocation(month, selected.id, { err: "write_not_allowed" }));
  const row = await getTransactionForUserEdit(env, id, selected.id);
  if (!row) return redirectResponse(myReturnLocation(month, selected.id, { err: "record_not_found" }));
  if (!canManageMyRecord(selected.role, row, userId)) return redirectResponse(myReturnLocation(month, selected.id, { err: "not_my_record" }));
  // V22.9.43: 구성원 권한이 ‘기록만’이면 자기 기록이어도 고치거나 지우지 못한다.
  const policyError = await memberRecordChangeError(env, selected.role, selected.id);
  if (policyError) return redirectResponse(myReturnLocation(month, selected.id, { err: policyError }));
  const transactionDate = String(form.get("transaction_date") || row.transaction_date || formatDate(nowKstDate())).trim();
  const amount = parseMyAmount(form);
  if (!amount || amount <= 0) return redirectResponse(myReturnLocation(month, selected.id, { err: "amount_required" }));
  if (amount > MAX_TRANSACTION_AMOUNT) return redirectResponse(myReturnLocation(month, selected.id, { err: "amount_too_large" }));
  if (!isValidTransactionDateString(transactionDate)) return redirectResponse(myReturnLocation(month, selected.id, { err: "invalid_date" }));
  const members = await fetchHouseholdMembers(env, selected.id);
  const requestedUserId = String(form.get("user_id") || "").trim();
  if (requestedUserId && !activeSpenderExists(members, requestedUserId)) return redirectResponse(myReturnLocation(month, selected.id, { err: "spender_not_member" }));
  const patch = {
    type: normalizeTransactionType(String(form.get("type") || row.type || "expense")),
    transaction_date: transactionDate,
    amount,
    memo: String(form.get("memo") || "").trim(),
    category: String(form.get("category") || "").trim(),
    payment_method: String(form.get("payment_method") || "").trim(),
    user_id: canManageAllRecords(selected.role) && requestedUserId && activeSpenderExists(members, requestedUserId) ? requestedUserId : row.user_id,
  };
  try {
    await updateTransaction(env, id, patch, { householdId: selected.id, actorUserId: userId, actorKind: "user" });
    try {
      await appendTransactionEditHistory(env, selected.id, id, row, { ...row, ...patch }, userId, members);
    } catch (historyError) {
      // The atomic transaction RPC already committed the edit and its database
      // audit. A secondary display-history failure must not tell the user that
      // the transaction itself failed or encourage a duplicate retry.
      rememberOpsEvent({ kind: "transaction_edit_history_save_failed", severity: "warn", path: "/my/update", method: "POST", detail: safeError(historyError) });
    }
    return redirectResponse(myReturnLocation(String(transactionDate).slice(0, 7) || month, selected.id, { msg: "updated" }));
  } catch (err) {
    rememberOpsEvent({ kind: "my_record_update_failed", severity: "warn", path: "/my/update", method: "POST", detail: safeError(err) });
    // V22.9.79 D-5: 환불과 연결된 기록의 종류·금액·환급 분류·날짜를 바꾸면 DB 트리거(refund_link_guard_v22979)가 막는다.
    // V22.9.80 T-12: 트리거가 알려 준 이유(종류·금액·환급 분류·날짜)별 코드로 돌려보낸다. 이유를 모르면 refund_link_locked.
    const refundLocked = refundLinkLockedCode(err);
    return redirectResponse(myReturnLocation(month, selected.id, { err: isUncertainStorageWrite(err) ? "db_write_unknown" : refundLocked || "record_update_failed" }));
  }
}

async function handleMyDeleteTransaction(request, env) {
  const userId = await verifyUserSession(request, env);
  if (!userId) return redirectResponse("/my");
  const form = await request.formData();
  const id = String(form.get("id") || "").trim();
  const month = validMonth(String(form.get("month") || "")) || currentMonthKst();
  const householdId = String(form.get("household_id") || "").trim();
  const { selected } = await getMySelectedHousehold(env, userId, householdId);
  if (!selected) return redirectResponse("/my?err=no_household");
  if (!canWriteMyHousehold(selected.role)) return redirectResponse(myReturnLocation(month, selected.id, { err: "write_not_allowed" }));
  const row = await getTransactionForUserEdit(env, id, selected.id);
  if (!row) return redirectResponse(myReturnLocation(month, selected.id, { err: "record_not_found" }));
  if (!canManageMyRecord(selected.role, row, userId)) return redirectResponse(myReturnLocation(month, selected.id, { err: "not_my_record" }));
  // V22.9.43: 구성원 권한이 ‘기록만’이면 자기 기록이어도 고치거나 지우지 못한다.
  const policyError = await memberRecordChangeError(env, selected.role, selected.id);
  if (policyError) return redirectResponse(myReturnLocation(month, selected.id, { err: policyError }));
  try {
    await deleteTransactionWithAudit(env, id, selected.id, { actorUserId: userId, actorKind: "user" });
    return redirectResponse(myReturnLocation(month, selected.id, { msg: "deleted" }));
  } catch (err) {
    rememberOpsEvent({ kind: "my_record_delete_failed", severity: "warn", path: "/my/delete", method: "POST", detail: safeError(err) });
    return redirectResponse(myReturnLocation(month, selected.id, { err: isUncertainStorageWrite(err) ? "db_write_unknown" : "record_delete_failed" }));
  }
}

function householdTemplatePreset(key = "") {
  const presets = {
    household: { name: "우리집 생활비", label: "생활비" },
    travel: { name: "우리 여행 경비", label: "여행" },
    meeting: { name: "우리 모임 회비", label: "모임" },
    settlement: { name: "단발성 정산", label: "정산" },
    family_event: { name: "가족 행사비", label: "가족 행사" },
  };
  return presets[String(key || "").trim()] || null;
}

